import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

const schema = z.object({
  os: z.enum(["ubuntu", "windows", "custom"]),
  customIsoPath: z.string().optional(),
  cpuCores: z.number().min(1).max(16),
  ram: z.number().min(512).max(16384),
  diskSize: z.number().min(10).max(500),
  enableKvm: z.boolean(),
  enableUsb: z.boolean(),
});

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const data = schema.parse(body);

    // Generate PowerShell script
    let script = `# QEMU Setup Script for Windows
# Generated by QEMU Setup Wizard

# Download and install QEMU (adjust version as needed)
$qemuUrl = "https://qemu.weilnetz.de/w64/qemu-w64-setup-20230822.exe"  # Official Windows installer
Invoke-WebRequest -Uri $qemuUrl -OutFile "qemu-installer.exe"
Start-Process -FilePath "qemu-installer.exe" -ArgumentList "/S" -Wait  # Silent install

# Set variables from config
$vmName = "MyVM"
$diskPath = "$vmName.qcow2"
$isoPath = switch ($data.os) {
  "ubuntu" { "path/to/ubuntu.iso" }  # User should replace with actual path
  "windows" { "path/to/windows.iso" }
  "custom" { $data.customIsoPath }
  default { "path/to/iso.iso" }
}
$cpu = $data.cpuCores
$memory = $data.ram
$disk = $data.diskSize * 1GB

# Create disk image
qemu-img create -f qcow2 $diskPath $disk

# Launch command
$launchCmd = "qemu-system-x86_64 -m $memory -smp $cpu -drive file=$diskPath,format=qcow2 -cdrom $isoPath"
if ($data.enableKvm) { $launchCmd += " -accel kvm" }
if ($data.enableUsb) { $launchCmd += " -usb -device usb-host,vendorid=0x1234,productid=0x5678" }  # Example USB passthrough

Start-Process -FilePath "qemu-system-x86_64" -ArgumentList $launchCmd

Write-Host "VM launched successfully!"
`;

    return NextResponse.json({ script });
  } catch (error) {
    return NextResponse.json({ error: "Invalid input" }, { status: 400 });
  }
}
